export const SOURCES: CourseSource[] = [
  { id: 'fresh-start-effect', title: 'Dai, Milkman y Riis · 2014 · El efecto del nuevo comienzo', url: 'https://faculty.wharton.upenn.edu/wp-content/uploads/2014/06/Dai_Fresh_Start_2014_Mgmt_Sci.pdf', type: 'research', finding: 'En tres conjuntos de datos de campo, la conducta orientada a metas aumentó al inicio de nuevos periodos de tiempo: las búsquedas en Google de «dieta» subieron 14.4% al inicio de una semana y 82.1% al inicio de un año; las visitas al gimnasio de 11,912 estudiantes universitarios subieron 33.4% al inicio de una semana y 47.1% al inicio de un semestre; los nuevos compromisos de metas en el sitio stickK subieron 62.9% al inicio de una semana y 145.3% al inicio de un año.', limitation: 'Son datos de campo observacionales que no ponen a prueba el mecanismo de forma directa; se fijan sobre todo en hitos compartidos del calendario y no muestran cuánto dura el impulso adicional. Los autores señalan que el aumento tras los días festivos se desvaneció rápido.' },
  { id: 'fresh-start-framing', title: 'Dai, Milkman y Riis · 2015 · Hitos temporales y experimentos sobre el inicio de metas', url: 'https://anderson-review.ucla.edu/wp-content/uploads/2021/03/Dai-Milkman-Riis_2015_TemporalLandmarks_APS_0956797615605818.pdf', type: 'research', finding: 'En cinco experimentos, presentar un día como un nuevo comienzo aumentó el deseo de empezar una meta: entre 165 participantes, 25.6% eligió un recordatorio de meta para el 20 de marzo cuando se presentaba como «el primer día de primavera», frente a 7.2% cuando se llamaba «el tercer jueves de marzo». El efecto se explicó por sentirse psicológicamente lejos de su yo pasado e imperfecto.', limitation: 'Experimentos breves con participantes en línea; las medidas son sobre todo intenciones, elecciones de recordatorio y escenarios hipotéticos. No muestran un cambio de conducta real y duradero.' },
  { id: 'bandura-self-efficacy', title: 'Bandura · 1977 · La teoría de la autoeficacia', url: 'https://eric.ed.gov/?id=EJ161632', type: 'research', finding: 'Bandura propone que el cambio psicológico funciona a través de la autoeficacia, la expectativa de que puedes llevar a cabo una conducta, y nombra cuatro fuentes de esa expectativa: las experiencias de logro, observar a otros (experiencia vicaria), la persuasión verbal y el estado fisiológico. Considera las experiencias de logro como la fuente más poderosa porque se apoyan en un logro personal, y escribe que una creencia fortalecida por éxitos repetidos se ve menos sacudida por fracasos ocasionales.', limitation: 'Es un artículo teórico de Psychological Review; no presenta un experimento nuevo ni un tamaño del efecto, y se apoya en gran medida en estudios sobre el tratamiento del miedo de su época.' },
  { id: 'self-efficacy-work-meta', title: 'Stajkovic y Luthans · 1998 · Metaanálisis de la autoeficacia y el desempeño laboral', url: 'https://doi.org/10.1037/0033-2909.124.2.240', type: 'research', finding: 'Un metaanálisis que reunió 114 estudios (157 tamaños del efecto, 21,616 personas) encontró una relación significativa y moderada entre la autoeficacia y el desempeño laboral (r promedio ponderado = 0.38).', limitation: 'Solo se leyó el resumen. Es un hallazgo correlacional; por sí solo no muestra hasta qué punto la autoeficacia causa el desempeño, y proviene de tareas laborales.' },
  { id: 'todo-list-bedtime', title: 'Scullin et al. · 2018 · Escribir una lista de pendientes antes de dormir y quedarse dormido', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5758411/', type: 'research', finding: 'En un laboratorio del sueño, 57 adultos jóvenes sanos de 18 a 30 años dedicaron 5 minutos antes de acostarse a escribir las tareas que debían hacer en los días siguientes o las tareas que habían completado en los días recientes. Quienes escribieron una lista de pendientes se durmieron más rápido, y cuanto más específica era la lista, más rápido se durmieron.', limitation: 'Una sola noche en laboratorio con una muestra pequeña y joven; no muestra si ocurre lo mismo en personas con insomnio ni a largo plazo. Solo se leyó el resumen.' },
  { id: 'franklin-daily-questions', title: 'Benjamin Franklin · Autobiografía · Preguntas de la mañana y de la noche', url: 'https://www.gutenberg.org/ebooks/20203', type: 'technique', finding: 'Como parte de su plan para llevar el registro de sus virtudes, Franklin describe un horario que organiza su día hora por hora: al levantarse y planear los asuntos del día se pregunta «¿Qué bien haré hoy?», y al repasar el día por la noche, «¿Qué bien he hecho hoy?».', limitation: 'Es un relato histórico en primera persona, de dominio público; no es un método probado científicamente.' },
  { id: 'oettingen-woop-method', title: 'Gabriele Oettingen · WOOP · Rethinking Positive Thinking (2014)', url: 'https://woopmylife.org/en/home', type: 'technique', finding: 'El método WOOP de Oettingen tiene cuatro pasos: Wish (deseo), Outcome (resultado), Obstacle (obstáculo), Plan. En lugar de limitarte a soñar en positivo, te pide contrastar el resultado que quieres con el obstáculo real que tienes delante y hacer un plan «si… entonces…» para ese obstáculo.', limitation: 'El contraste mental y la planificación «si… entonces…» en los que se apoya el método mostraron efectos promedio de pequeños a medianos en la investigación; el sitio oficial pertenece a quienes desarrollaron el método y no es una evaluación independiente.' },
  { id: 'clear-two-minute-rule', title: 'James Clear · La regla de los dos minutos · Atomic Habits (2018)', url: 'https://jamesclear.com/how-to-stop-procrastinating', type: 'technique', finding: 'La regla tiene dos partes: el consejo de David Allen de hacer de inmediato cualquier cosa que tome menos de dos minutos, y la adaptación de Clear de que un hábito nuevo debe empezar con un primer paso que tome menos de dos minutos, por ejemplo leer una página en lugar de leer durante una hora.', limitation: 'Es una sugerencia práctica; la regla en sí no se ha puesto a prueba directamente en estudios controlados.' },
  { id: 'fogg-anchor-recipe', title: 'BJ Fogg · Tiny Habits (2019)', url: 'https://tinyhabits.com/', type: 'technique', finding: 'Fogg, que dirige el Behavior Design Lab de Stanford, sugiere hacer una conducta nueva muy pequeña, atarla justo después de un «ancla» que ya haces cada día y celebrar brevemente en cuanto la hayas hecho.', limitation: 'Es coherente con los hallazgos de que repetir en el mismo contexto fortalece los hábitos, pero el método en sí, sobre todo el paso de celebrar, ha tenido pocas pruebas en estudios aleatorizados independientes.' },
  { id: 'seinfeld-chain-story', title: '«No rompas la cadena», atribuido a Jerry Seinfeld · según lo cuenta James Clear', url: 'https://jamesclear.com/stop-procrastinating-seinfeld-strategy', type: 'technique', finding: 'En la historia, pones una gran X en un calendario de pared por cada día que haces el trabajo, y la meta es no romper la cadena que se forma, desplazando la atención del resultado de un día concreto hacia la constancia.', limitation: 'Es una anécdota que el comediante Brad Isaac contó a Lifehacker; según la nota de Clear, Seinfeld ha dicho que la idea no era suya y que no afirmó usarla. El método no se ha puesto a prueba directamente.' },
  { id: 'habits', title: 'Lally et al. · 2010 · La formación de hábitos en la vida cotidiana', url: 'https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674', type: 'research', finding: 'Tras seguir a 96 voluntarios durante 12 semanas, el estudio registró la repetición en el mismo contexto y la automaticidad creciente; el tiempo que tomó varió mucho entre personas, y omitir una conducta una vez no afectó de forma notable el proceso de formación del hábito.', limitation: 'Es un estudio observacional basado en autorreporte; no da un número fijo de días válido para todos. Se leyó el resumen de la editorial.' },
  { id: 'turning-day-commitment-contract', title: 'Giné, Karlan y Zinman · 2010 · Un contrato de compromiso para dejar de fumar', url: 'https://www.aeaweb.org/articles?id=10.1257%2Fapp.2.4.213', type: 'research', finding: 'A fumadores se les ofreció una cuenta de ahorro: depositaban dinero durante seis meses y luego se hacían una prueba de orina para detectar nicotina y cotinina. Si la pasaban, se les devolvía el dinero; si no, iba a una organización benéfica. 11% de quienes recibieron la oferta se inscribió. Los fumadores a quienes se les ofreció al azar tuvieron 3 puntos porcentuales más de probabilidad de pasar la prueba a los seis meses, y la diferencia se mantuvo en pruebas sorpresa a los 12 meses.', limitation: 'Solo se leyó el resumen. Es un experimento de campo sobre una sola conducta (fumar); la aceptación fue baja y el efecto promedio pequeño. Muestra que un mecanismo de compromiso puede ayudar a algunas personas, no que le sirva a todo el mundo.' },
];

